#!/usr/bin/env node
// generated by zed-pkg-test/test-org-fleet
import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { readFleetManifest } from './read-fleet-manifest.mjs';

const root = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..');
const manifestPath = process.argv.find((arg) => arg.endsWith('.json') || arg.endsWith('.json.gz')) ?? path.join(root, 'bootstrap', 'test-org-fleet.json.gz');
const manifest = readFleetManifest(manifestPath);
const serialized = JSON.stringify(manifest);
const errors = [];
const warnings = [];
const fail = (message) => errors.push(message);
const warn = (message) => warnings.push(message);
const seen = new Set();
const excluded = new Set(manifest.policy?.excludedOrganizations ?? []);
const allowedModes = new Set(manifest.policy?.dependencyModes ?? []);

if (manifest.schemaVersion !== 1) fail(`schemaVersion must be 1, got ${manifest.schemaVersion}`);
if (!Array.isArray(manifest.pairs) || manifest.pairs.length === 0) fail('pairs must be a non-empty array');
if (!manifest.profiles || typeof manifest.profiles !== 'object') fail('profiles must be an object');
if (!excluded.has('r2g') || !excluded.has('r2g-test')) fail('r2g and r2g-test must remain explicitly excluded');

let createCount = 0;
let existingCount = 0;
let importCount = 0;
const managers = new Map();

for (const pair of manifest.pairs ?? []) {
  const key = `${pair.sourceOrg}=>${pair.testOrg}`;
  if (seen.has(key)) fail(`duplicate pair ${key}`);
  seen.add(key);
  if (excluded.has(pair.sourceOrg) || excluded.has(pair.testOrg)) fail(`excluded organization leaked into pair ${key}`);
  if (!pair.testOrg?.toLowerCase().endsWith('-test')) fail(`test org must end in -test: ${pair.testOrg}`);
  if (!['public', 'private'].includes(pair.defaultVisibility)) fail(`invalid defaultVisibility for ${pair.testOrg}`);
  if (!Array.isArray(pair.repositories) || pair.repositories.length === 0) fail(`no repositories for ${pair.testOrg}`);

  const repoNames = new Set();
  for (const existing of pair.existingRepositories ?? []) {
    existingCount += 1;
    if (repoNames.has(existing)) fail(`duplicate existing repository ${pair.testOrg}/${existing}`);
    repoNames.add(existing);
  }

  for (const repository of pair.repositories ?? []) {
    createCount += repository.state === 'create' ? 1 : 0;
    if (!/^[a-z0-9._-]+$/.test(repository.name)) fail(`invalid repository name ${pair.testOrg}/${repository.name}`);
    if (repoNames.has(repository.name)) fail(`duplicate repository ${pair.testOrg}/${repository.name}`);
    repoNames.add(repository.name);
    if (!manifest.profiles?.[repository.profile]) fail(`unknown profile ${repository.profile} for ${pair.testOrg}/${repository.name}`);
    if (!Array.isArray(repository.sources) || repository.sources.length === 0) fail(`no sources for ${pair.testOrg}/${repository.name}`);
    if (!Array.isArray(repository.focus) || repository.focus.length < 2) warn(`shallow focus list for ${pair.testOrg}/${repository.name}`);
    for (const source of repository.sources ?? []) {
      if (!/^[^/]+\/[^/]+$/.test(source)) fail(`invalid source ${source} for ${pair.testOrg}/${repository.name}`);
      if (excluded.has(source.split('/')[0])) fail(`excluded source ${source} in ${pair.testOrg}/${repository.name}`);
    }
    for (const dependency of repository.imports ?? []) {
      importCount += 1;
      if (!allowedModes.has(dependency.mode)) fail(`unsupported import mode ${dependency.mode} in ${pair.testOrg}/${repository.name}`);
      if (!/^[^/]+\/[^/]+$/.test(dependency.source ?? '')) fail(`invalid import source in ${pair.testOrg}/${repository.name}`);
      if (dependency.mode === 'git-submodule' && !dependency.path) fail(`submodule missing path in ${pair.testOrg}/${repository.name}`);
      if (dependency.mode === 'native-package') {
        if (!dependency.manager) fail(`native package missing manager in ${pair.testOrg}/${repository.name}`);
        managers.set(dependency.manager, (managers.get(dependency.manager) ?? 0) + 1);
      }
    }
  }
}

const fiducia = manifest.pairs?.find((pair) => pair.testOrg === 'fiducia-cloud-test');
const fiduciaClients = fiducia?.repositories?.filter((repository) => /^fiducia-.+-client-e2e$/.test(repository.name)) ?? [];
if (fiduciaClients.length !== 10) fail(`fiducia-cloud-test must define exactly 10 language client repos; found ${fiduciaClients.length}`);
for (const repository of fiduciaClients) {
  const modes = new Set(repository.imports?.map((dependency) => dependency.mode));
  for (const required of ['git-submodule', 'zed', 'native-package']) {
    if (!modes.has(required)) fail(`${repository.name} missing ${required} lane`);
  }
}

for (const pattern of [/ghp_[A-Za-z0-9]+/, /github_pat_[A-Za-z0-9_]+/, /Bearer\s+[A-Za-z0-9._-]{20,}/i]) {
  if (pattern.test(serialized)) fail(`credential-shaped value found in ${manifestPath}`);
}

const summary = {
  schemaVersion: manifest.schemaVersion,
  pairs: manifest.pairs?.length ?? 0,
  governanceRepositories: manifest.pairs?.length ?? 0,
  createRepositories: createCount,
  existingRepositories: existingCount,
  imports: importCount,
  nativeManagers: Object.fromEntries([...managers.entries()].sort(([a], [b]) => a.localeCompare(b))),
  warnings: warnings.length,
  errors: errors.length,
};

if (process.argv.includes('--json')) {
  process.stdout.write(`${JSON.stringify(summary, null, 2)}\n`);
} else {
  console.log(`validated ${summary.pairs} org pairs, ${summary.createRepositories} create repos, ${summary.governanceRepositories} governance repos, ${summary.existingRepositories} existing fixtures, ${summary.imports} dependency lanes`);
  for (const message of warnings) console.warn(`warning: ${message}`);
}
if (errors.length) {
  for (const message of errors) console.error(`error: ${message}`);
  process.exit(1);
}
